def _timestamps() -> tuple[sa.Column, sa.Column]:
    return (sa.Column('created_at', sa.DateTime(timezone=True), nullable=False, server_default=sa.text('now()')), sa.Column('updated_at', sa.DateTime(timezone=True), nullable=False, server_default=sa.text('now()')))

def _index(table_name: str, name: str, columns: list[object], **kwargs: object) -> sa.Index:
    table = Base.metadata.tables[table_name]
    expressions = [table.c[column] if isinstance(column, str) else column for column in columns]
    return sa.Index(name, *expressions, **kwargs)

def _append_unique(table_name: str, name: str, columns: list[str]) -> None:
    table = Base.metadata.tables[table_name]
    if name not in {constraint.name for constraint in table.constraints}:
        table.append_constraint(sa.UniqueConstraint(*columns, name=name))

def _replace_check(table_name: str, name: str, condition: str) -> None:
    table = Base.metadata.tables[table_name]
    for constraint in tuple(table.constraints):
        if constraint.name == name:
            table.constraints.remove(constraint)
    table.append_constraint(sa.CheckConstraint(condition, name=name))

